CREATE POLICY rls09_rounds_insert ON public.rounds FOR INSERT TO authenticated WITH CHECK(((EXISTS ( SELECT 1
   FROM events e
  WHERE ((e.id = rounds.event_id) AND ((auth.uid() IS NOT NULL) AND (NOT COALESCE(e.is_deleted, false)) AND (is_super_user() OR ((e.club_id IS NULL) AND (e.created_by_auth_user_id = auth.uid())) OR (EXISTS ( SELECT 1
           FROM (club_members cm
             LEFT JOIN player_profiles pp ON ((pp.id = cm.player_profile_id)))
          WHERE ((cm.club_id = e.club_id) AND cm.is_active AND ((cm.profile_id = auth.uid()) OR (pp.linked_auth_user_id = auth.uid()))))) OR ((e.event_mode = 'team'::text) AND can_manage_friendly_team_event_by_sides(e.id, e.created_by_auth_user_id)))))))) AND (true));
